# Immutable observed service index preserves the original runtime subject and keeps that service unchanged.
FROM registry.depot.dev/27m5m3vjlv@sha256:4f2c182b14f816dfe9ab08f531a8d49378b5f76767b8f56f7c9154f05d0ff3e7
ARG CI_IMAGE_HARNESS_SHA
RUN ["node","--input-type=module-typescript","-e","import {execFileSync} from 'node:child_process';
import {mkdirSync,writeFileSync,rmSync} from 'node:fs';
import {strict as assert} from 'node:assert';
const packages=['ca-certificates','curl','git','gzip','tar','xz-utils','zstd'];
const env={...process.env,DEBIAN_FRONTEND:'noninteractive'};
execFileSync('apt-get',['update'],{stdio:'inherit',env});
execFileSync('apt-get',['install','--assume-yes','--no-install-recommends',...packages],{stdio:'inherit',env});
const commands={git:['--version'],curl:['--version'],tar:['--version'],gzip:['--version'],xz:['--version'],zstd:['--version'],bash:['--version']};
const tools=Object.fromEntries(Object.entries(commands).map(([name,args])=>[name,execFileSync(name,args,{encoding:'utf8'})]));
assert(/^git version 2[.](?:[2-9][0-9]|1[89])[.]/u.test(tools.git));
assert(execFileSync('tar',['--zstd','--version'],{encoding:'utf8'}).includes('tar'));
const installedPackages=execFileSync('dpkg-query',['--show','--showformat='+String.fromCharCode(36)+'{Package}\t'+String.fromCharCode(36)+'{Version}\n',...packages],{encoding:'utf8'});
const receipt={architecture:process.arch,nodeVersion:process.version,harnessCommit:process.env.CI_IMAGE_HARNESS_SHA,
  serviceBase:'registry.depot.dev/27m5m3vjlv@sha256:4f2c182b14f816dfe9ab08f531a8d49378b5f76767b8f56f7c9154f05d0ff3e7',
  miseAction:'c2a87611a18de5b3828c5652fe268e992400cb5c',tools,installedPackages};
mkdirSync('/opt/depot-research',{recursive:true});writeFileSync('/opt/depot-research/image-tools.json',JSON.stringify(receipt));
rmSync('/var/lib/apt/lists',{recursive:true,force:true});"]
HEALTHCHECK NONE
CMD ["bash"]

# Prior failed CI image retained; repository Node26 loader requires libatomic1.
FROM registry.depot.dev/27m5m3vjlv@sha256:aab45816f04afec0aed6ccd0daea92e6288a4a35c65368438678bad30b57f346
ARG CI_NODE26_HARNESS_SHA
RUN ["node","--input-type=module-typescript","-e","import {readFileSync,writeFileSync,mkdtempSync,rmSync,statSync} from 'node:fs';
import {execFileSync} from 'node:child_process';import {createHash} from 'node:crypto';import {strict as assert} from 'node:assert';
const hash=value=>createHash('sha256').update(value).digest('hex');
const archives={"x64":{"url":"https://nodejs.org/dist/v26.12.0/node-v26.12.0-linux-x64.tar.gz","sha256":"d9f88af72ad34f7ddf8e67289829f1698f54b6254f7d4f54b7453117ff1a3d2c"},"arm64":{"url":"https://nodejs.org/dist/v26.12.0/node-v26.12.0-linux-arm64.tar.gz","sha256":"ec53c915c3fdd8786c5685abd25ae3fe9fba0692307f9811d7caaadea1bcaf03"}};const input=archives[process.arch];assert(input);
const env={...process.env,DEBIAN_FRONTEND:'noninteractive'};
execFileSync('apt-get',['update'],{stdio:'inherit',env});
execFileSync('apt-get',['install','--assume-yes','--no-install-recommends','libatomic1'],{stdio:'inherit',env});
const scratch=mkdtempSync('/var/tmp/depot-node26-runtime-');
try{
 const response=await fetch(input.url,{signal:AbortSignal.timeout(45000)});assert.equal(response.status,200);
 const bytes=Buffer.from(await response.arrayBuffer());assert(bytes.length<100*1024**2);assert.equal(hash(bytes),input.sha256);
 const archive=scratch+'/node.tar.gz';writeFileSync(archive,bytes);
 execFileSync('tar',['--extract','--gzip','--file',archive,'--directory',scratch,'--strip-components','1']);
 const binary=scratch+'/bin/node';const header=readFileSync(binary);assert.equal(header.subarray(0,4).toString('hex'),'7f454c46');
 const machine=header.readUInt16LE(18);assert.equal(machine,process.arch==='x64'?62:183);
 const ldd=execFileSync('ldd',[binary],{encoding:'utf8'});assert(!ldd.includes('not found'));assert(ldd.includes('libatomic.so.1 =>'));
 const probeProgram="import {createHash} from 'node:crypto';const marker: string='monochromatic-node26-runtime';"+
  "await Promise.resolve();process.stdout.write(JSON.stringify({version:process.version,architecture:process.arch,"+
  "sha256:createHash('sha256').update(marker).digest('hex'),versions:process.versions}));";
 const stdout=execFileSync(binary,['--input-type=module-typescript','-e',probeProgram],{encoding:'utf8'});
 const probe=JSON.parse(stdout);assert.equal(probe.version,'v26.12.0');assert.equal(probe.architecture,process.arch);
 assert.equal(probe.sha256,hash('monochromatic-node26-runtime'));
 const original=JSON.parse(readFileSync('/opt/depot-research/image-tools.json','utf8'));
 const packageOutput=execFileSync('dpkg-query',['--show','--showformat='+String.fromCharCode(36)+'{Package}\t'+
  String.fromCharCode(36)+'{Version}\t'+String.fromCharCode(36)+'{Architecture}\n','libatomic1'],{encoding:'utf8'});
 const receipt={...original,priorHarnessCommit:original.harnessCommit,harnessCommit:process.env.CI_NODE26_HARNESS_SHA,
  originalCiBase:'registry.depot.dev/27m5m3vjlv@sha256:aab45816f04afec0aed6ccd0daea92e6288a4a35c65368438678bad30b57f346',repositoryBase:'e02be6c8b8fe9efb41a7f8f1a0b311c17796588a',
  nodeVersion:process.version,libatomicPackage:packageOutput,
  repositoryNode:{...input,archiveBytes:bytes.length,binarySha256:hash(header),binaryBytes:statSync(binary).size,
   elfMachine:machine,ldd,probe,retainedInstallation:false}};
 writeFileSync('/opt/depot-research/image-tools.json',JSON.stringify(receipt));
 process.stdout.write(JSON.stringify({architecture:process.arch,baseNode:process.version,repositoryNode:probe.version,
  libatomicPackage:packageOutput,harnessCommit:receipt.harnessCommit})+'\n');
}finally{rmSync(scratch,{recursive:true,force:true});}
rmSync('/var/lib/apt/lists',{recursive:true,force:true});"]
HEALTHCHECK NONE
CMD ["bash"]
